740→const TYPE_COLORS = {
741→  lesson: '#4a9eff', correction: '#ff6666', interaction: '#33ff88',
742→  rule: '#ffaa33', decision: '#aa66ff', mental_model: '#33dddd',
743→  mechanism: '#dddd33', vocabulary: '#666', context: '#555',
744→  bug_lesson: '#ff8866', pattern: '#ff66aa', boot: '#888',
