759→function initGraph() {
760→  if (graphInited) return;
761→  graphInited = true;
762→  canvas = document.getElementById('graph-canvas');
763→  ctx = canvas.getContext('2d');
764→  resizeCanvas();
765→  window.addEventListener('resize', resizeCanvas);
766→  canvas.addEventListener('mousedown', onMouseDown);
767→  canvas.addEventListener('mousemove', onMouseMove);
768→  canvas.addEventListener('mouseup', onMouseUp);
769→  canvas.addEventListener('wheel', onWheel);
