772→
773→function resizeCanvas() {
774→  if (!canvas) return;
775→  const rect = canvas.parentElement.getBoundingClientRect();
776→  if (rect.width === 0 || rect.height === 0) return;
777→  canvas.width = rect.width * devicePixelRatio;
778→  canvas.height = rect.height * devicePixelRatio;
779→  canvas.style.width = rect.width + 'px';
780→  canvas.style.height = rect.height + 'px';
781→  ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
782→}
783→
784→function initForce() {
785→  if (!graphData) return;
786→  const w = canvas.width / devicePixelRatio;
787→  const h = canvas.height / devicePixelRatio;
788→  graphNodes = graphData.nodes.map((n, i) => ({
789→    ...n, x: w/2 + (Math.random()-0.5)*300,
790→    y: h/2 + (Math.random()-0.5)*300,
791→    vx: 0, vy: 0,
792→    radius: Math.max(4, Math.min(16, Math.sqrt(n.access_count || 1) * 2)),
793→  }));
794→  const idMap = {};
795→  graphNodes.forEach((n, i) => idMap[n.id] = i);
796→  graphEdges = graphData.edges.filter(e => idMap[e.source] !== undefined && idMap[e.target] !== undefined)
797→    .map(e => ({ source: idMap[e.source], target: idMap[e.target], relation: e.relation, weight: e.weight }));
798→  simulate();
799→}
800→
801→function simulate() {
802→  let iterations = 0;
803→  function tick() {
804→    if (iterations > 300) { render(); return; }
805→    iterations++;
806→    const n = graphNodes.length;
807→    // Repulsion
808→    for (let i = 0; i < n; i++) {
809→      for (let j = i+1; j < n; j++) {
810→        let dx = graphNodes[j].x - graphNodes[i].x;
811→        let dy = graphNodes[j].y - graphNodes[i].y;
812→        let d = Math.sqrt(dx*dx + dy*dy) || 1;
813→        let force = 400 / (d * d);
814→        graphNodes[i].vx -= dx/d * force;
815→        graphNodes[i].vy -= dy/d * force;
816→        graphNodes[j].vx += dx/d * force;
817→        graphNodes[j].vy += dy/d * force;
818→      }
819→    }
820→    // Attraction (edges)
821→    for (const e of graphEdges) {
822→      const a = graphNodes[e.source], b = graphNodes[e.target];
823→      let dx = b.x - a.x, dy = b.y - a.y;
824→      let d = Math.sqrt(dx*dx + dy*dy) || 1;
825→      let force = (d - 40) * 0.02;
826→      a.vx += dx/d * force; a.vy += dy/d * force;
827→      b.vx -= dx/d * force; b.vy -= dy/d * force;
828→    }
829→    // Center gravity
830→    const cx = (canvas.width/devicePixelRatio)/2, cy = (canvas.height/devicePixelRatio)/2;
831→    for (const node of graphNodes) {
832→      node.vx += (cx - node.x) * 0.005;
833→      node.vy += (cy - node.y) * 0.005;
834→      node.vx *= 0.9; node.vy *= 0.9;
835→      node.x += node.vx; node.y += node.vy;
836→    }
837→    render();
838→    requestAnimationFrame(tick);
839→  }
840→  tick();
841→}
842→
843→function render() {
844→  const w = canvas.width / devicePixelRatio;
845→  const h = canvas.height / devicePixelRatio;
846→  ctx.clearRect(0, 0, w, h);
847→  ctx.save();
848→  ctx.translate(offsetX, offsetY);
849→  ctx.scale(scale, scale);
850→
851→  // Edges
852→  ctx.globalAlpha = 0.15;
853→  for (const e of graphEdges) {
854→    const a = graphNodes[e.source], b = graphNodes[e.target];
855→    ctx.strokeStyle = '#4a4a6a';
856→    ctx.lineWidth = 0.5;
857→    ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
858→  }
859→
860→  // Nodes
861→  ctx.globalAlpha = 1;
862→  for (const n of graphNodes) {
863→    ctx.fillStyle = TYPE_COLORS[n.type] || '#888';
864→    ctx.globalAlpha = n.locked ? 1 : 0.7;
865→    ctx.beginPath(); ctx.arc(n.x, n.y, n.radius, 0, Math.PI*2); ctx.fill();
866→    if (n.locked) {
867→      ctx.strokeStyle = '#ffaa33';
868→      ctx.lineWidth = 1.5;
869→      ctx.stroke();
870→    }
871→    if (n === hoveredNode) {
872→      ctx.strokeStyle = '#fff';
873→      ctx.lineWidth = 2;
874→      ctx.stroke();
875→    }
876→  }
877→
878→  // Labels for larger nodes
879→  ctx.globalAlpha = 0.8;
880→  ctx.fillStyle = '#ccc';
881→  ctx.font = '9px SF Mono, monospace';
882→  ctx.textAlign = 'center';
883→  for (const n of graphNodes) {
884→    if (n.radius > 6 || n === hoveredNode) {
885→      ctx.fillText(n.title.substring(0, 25), n.x, n.y + n.radius + 12);
886→    }
887→  }
888→  ctx.restore();
889→}
890→
891→function getNodeAt(mx, my) {
892→  const x = (mx - offsetX) / scale;
893→  const y = (my - offsetY) / scale;
894→  for (const n of graphNodes) {
895→    const dx = n.x - x, dy = n.y - y;
896→    if (dx*dx + dy*dy < (n.radius+4)*(n.radius+4)) return n;
897→  }
898→  return null;
899→}
900→
901→function onMouseDown(e) {
902→  const rect = canvas.getBoundingClientRect();
903→  const mx = e.clientX - rect.left, my = e.clientY - rect.top;
904→  dragNode = getNodeAt(mx, my);
905→  if (dragNode) { dragStartX = mx; dragStartY = my; }
906→  else { dragStartX = mx - offsetX; dragStartY = my - offsetY; }
907→}
908→function onMouseMove(e) {
909→  const rect = canvas.getBoundingClientRect();
910→  const mx = e.clientX - rect.left, my = e.clientY - rect.top;
911→  if (dragNode) {
912→    dragNode.x += (mx - dragStartX) / scale;
913→    dragNode.y += (my - dragStartY) / scale;
914→    dragStartX = mx; dragStartY = my;
915→    render();
916→  } else if (e.buttons === 1) {
917→    offsetX = mx - dragStartX; offsetY = my - dragStartY;
918→    render();
919→  } else {
920→    const n = getNodeAt(mx, my);
921→    if (n !== hoveredNode) {
922→      hoveredNode = n;
923→      render();
924→      const tt = document.getElementById('tooltip');
925→      if (n) {
926→        tt.style.display = 'block';
927→        tt.style.left = (mx + 15) + 'px';
928→        tt.style.top = (my + 15) + 'px';
929→        tt.innerHTML = `<div class="tt-title">${n.title}</div><div class="tt-type"><span class="type-badge type-${n.type}">${n.type}</span> ${n.locked?'🔒':''} accessed ${n.access_count}x</div>`;
930→      } else { tt.style.display = 'none'; }
931→    }
932→  }
933→}
934→function onMouseUp() { dragNode = null; }
935→function onWheel(e) {
936→  e.preventDefault();
937→  const rect = canvas.getBoundingClientRect();
938→  const mx = e.clientX - rect.left, my = e.clientY - rect.top;
939→  const delta = e.deltaY > 0 ? 0.9 : 1.1;
940→  const newScale = scale * delta;
941→  if (newScale < 0.1 || newScale > 10) return;
942→  offsetX = mx - (mx - offsetX) * delta;
943→  offsetY = my - (my - offsetY) * delta;
944→  scale = newScale;
945→  render();
946→}
947→</script>
948→</body>
