                db_dir = _os.path.dirname(_brain.db_path) if hasattr(_brain, 'db_path') else _os.path.dirname(str(c.execute("PRAGMA database_list").fetchone()[2]))
                logs_db = _os.path.join(db_dir, "brain_logs.db")
