                for k, v in result.items():
                    s = str(v)
                    obs_result[k] = s[:300] + "..." if len(s) > 300 else s

            self._observe("command", command=cmd, args=obs_args, result=obs_result)
        except Exception:
            pass

    def _dispatch(self, cmd: str, args: Dict[str, Any]) -> Dict[str, Any]:
