def find_node_by_title(self, title_query: str, threshold: float = 0.6) -> Optional[Dict[str, Any]]:
    """Find a node by fuzzy title matching using embedding similarity.

    Embeds the query, scans all node embeddings, returns the best match
    above threshold. Used by connect_by_title and encode_cluster.

    Returns: {id, title, type, similarity} or None if no match above threshold.
    """
    if not embedder.is_ready():
        return None
    query_vec = embedder.embed(title_query)
    if not query_vec:
        return None

    rows = self.conn.execute(
        "SELECT ne.node_id, ne.embedding, n.title, n.type "
        "FROM node_embeddings ne JOIN nodes n ON ne.node_id = n.id "
        "WHERE n.archived = 0"
    ).fetchall()

    best_id, best_title, best_type, best_sim = None, None, None, 0.0
    for node_id, emb_blob, title, ntype in rows:
        if not emb_blob:
            continue
        sim = embedder.cosine_similarity(query_vec, emb_blob)
        if sim > best_sim:
            best_id, best_title, best_type, best_sim = node_id, title, ntype, sim

    if best_sim >= threshold:
        return {"id": best_id, "title": best_title, "type": best_type, "similarity": round(best_sim, 3)}
    return None

